INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m1-tf1-01', 'set-stsi4207-m1-3', 'Fungsi sistem informasi adalah mengubah data menjadi ....', 'informasi', 'informatika', 'keputusan', 'kebutuhan', 'A', 'Fungsi utama sistem informasi adalah memproses data mentah menjadi informasi yang bermanfaat bagi pemakainya.', 1),
  ('q-stsi4207-m1-tf1-02', 'set-stsi4207-m1-3', 'Infrastruktur teknologi informasi guna berbagi data disebut ....', 'perangkat keras', 'perangkat lunak', 'perangkat telekomunikasi', 'penyimpanan data', 'C', 'Perangkat telekomunikasi dan jaringan merupakan infrastruktur TI yang berfungsi untuk saling berbagi data dan berkomunikasi.', 1),
  ('q-stsi4207-m1-tf1-03', 'set-stsi4207-m1-3', 'Tiga level hirarki organisasi yang umum dijumpai pada berbagai perusahaan adalah ....', 'manajemen puncak, manajemen operasional, pekerja', 'manajemen puncak, manajemen menengah, manajemen operasional', 'manajemen puncak, manajemen operasional, sistem informasi', 'manajemen puncak, manajemen menengah, pekerja', 'B', 'Tiga tingkatan hierarki manajerial dalam organisasi adalah manajemen puncak (strategic), manajemen menengah (tactical), dan manajemen operasional (operational).', 1),
  ('q-stsi4207-m1-tf1-04', 'set-stsi4207-m1-3', 'Point of sales yang mengolah data penjualan termasuk dalam tipe sistem informasi ....', 'sistem pembuatan keputusan', 'sistem pemrosesan transaksi', 'sistem pakar', 'sistem penjualan', 'B', 'Point of Sales (POS) adalah bagian dari Transaction Processing System (TPS) yang mencatat dan memproses transaksi penjualan rutin harian.', 1),
  ('q-stsi4207-m1-tf1-05', 'set-stsi4207-m1-3', 'Sistem terdiri dari komponen yang sering disebut sebagai ....', 'subsistem', 'supra sistem', 'sub sistem', 'sistemik', 'C', 'Komponen-komponen atau bagian yang lebih kecil yang membentuk suatu sistem disebut sebagai sub sistem.', 1),
  ('q-stsi4207-m1-tf1-06', 'set-stsi4207-m1-3', 'Informasi dibutuhkan guna membuat keputusan yang ....', 'maksimal', 'optimal', 'rasional', 'bilingual', 'C', 'Informasi yang akurat dan relevan diperlukan agar pengambil keputusan dapat bertindak secara rasional.', 1),
  ('q-stsi4207-m1-tf1-07', 'set-stsi4207-m1-3', 'Orang yang bertanggung jawab untuk menentukan arah dan tujuan suatu perusahaan adalah ....', 'manajer menengah', 'supervisor', 'mandor', 'manajer puncak', 'D', 'Manajer puncak (top manager/eksekutif) memegang tanggung jawab strategis menetapkan visi, misi, dan arah jangka panjang perusahaan.', 1),
  ('q-stsi4207-m1-tf1-08', 'set-stsi4207-m1-3', 'Operasi rutin harian suatu perusahaan merupakan tanggung jawab dari manajer ....', 'operasional', 'umum', 'puncak', 'HRD', 'A', 'Manajer operasional mengawasi dan mengendalikan jalannya aktivitas operasional harian perusahaan.', 1),
  ('q-stsi4207-m1-tf1-09', 'set-stsi4207-m1-3', 'Regulasi yang dikembangkan oleh suatu perusahaan guna menyelesaikan atau melaksanakan suatu tugas disebut proses ....', 'manual', 'otomatis', 'bisnis', 'digital', 'C', 'Aturan kerja, alur terkoordinasi, dan regulasi internal dalam menyelesaikan tugas organisasi disebut proses bisnis.', 1),
  ('q-stsi4207-m1-tf1-10', 'set-stsi4207-m1-3', 'Kumpulan instruksi yang digunakan untuk mengendalikan dan mengkoordinasikan sebuah komputer disebut perangkat ....', 'cadangan', 'catu daya', 'keras', 'lunak', 'D', 'Perangkat lunak (software) adalah sekumpulan instruksi terprogram yang mengatur kerja perangkat keras komputer.', 1),
  ('q-stsi4207-m1-tf2-01', 'set-stsi4207-m1-3', 'Munculnya layanan streaming film dan musik merupakan perkembangan bisnis berbasis teknologi informasi dalam bentuk ....', 'model usaha baru', 'proses bisnis baru', 'strategi usaha baru', 'pendapatan baru', 'A', 'Layanan streaming digital merupakan bentuk inovasi model bisnis/usaha baru (new business model) yang mengubah cara penyampaian nilai ke konsumen.', 1),
  ('q-stsi4207-m1-tf2-02', 'set-stsi4207-m1-3', 'Internet memungkinkan pengusaha UMKM di Indonesia berjualan ke luar negeri dengan cara menurunkan biaya ....', 'upah dan gaji', 'produksi', 'operasional', 'tak terduga', 'C', 'Pemanfaatan internet mereduksi biaya operasional fisik dan saluran distribusi secara signifikan sehingga UMKM dapat menjangkau pasar global.', 1),
  ('q-stsi4207-m1-tf2-03', 'set-stsi4207-m1-3', 'Keunikan barang digital dibandingkan dengan barang konvensional adalah ....', 'biaya pemasaran sangat tinggi', 'keuntungan pasti besar', 'profit margin rendah', 'biaya produksi hanya sebesar biaya produksi unit pertama', 'D', 'Barang digital memiliki karakteristik zero marginal cost, di mana biaya pembuatan terkonsentrasi pada unit pertama, sedangkan biaya reproduksi berikutnya mendekati nol.', 1),
  ('q-stsi4207-m1-tf2-04', 'set-stsi4207-m1-3', 'Biaya untuk berpindah ke penjual lain bagi seorang konsumen disebut sebagai ....', 'switching cost', 'variable cost', 'fixed cost', 'shared cost', 'A', 'Switching cost adalah biaya, waktu, atau usaha yang harus dikeluarkan pelanggan saat memutuskan berpindah dari satu produk/penjual ke yang lain.', 1),
  ('q-stsi4207-m1-tf2-05', 'set-stsi4207-m1-3', 'Kualitas informasi ketepatan waktu biasanya berbanding terbalik dengan ....', 'ketersediaan akses', 'kelengkapan', 'kehandalan', 'kepercayaan', 'B', 'Semakin cepat informasi dituntut untuk segera disajikan (ketepatan waktu), sering kali ada kompromi pada kelengkapan detail data yang disajikan.', 1),
  ('q-stsi4207-m1-tf2-06', 'set-stsi4207-m1-3', 'Mesin Anjungan Tunai Mandiri merupakan contoh teknologi informasi yang berguna untuk ....', 'meraih keuntungan besar', 'keunggulan kompetitif', 'bertahan hidup', 'keunggulan non kompetitif', 'C', 'ATM menjadi keharusan standar bagi industri perbankan untuk bertahan hidup (survival) memenuhi ekspektasi dasar nasabah.', 1),
  ('q-stsi4207-m1-tf2-07', 'set-stsi4207-m1-3', 'Perkembangan teknologi yang secara drastis mengubah tatanan usaha di berbagai industri disebut sebagai ....', 'teknologi unggul', 'adopsi teknologi', 'difusi teknologi', 'disrupsi teknologi', 'D', 'Disrupsi teknologi (disruptive technology) mendobrak model bisnis konvensional dan menggantikannya dengan teknologi yang lebih efisien dan modern.', 1),
  ('q-stsi4207-m1-tf2-08', 'set-stsi4207-m1-3', 'Aplikasi yang memungkinkan suatu mesin dikendalikan melalui internet disebut sebagai ....', 'Internet of Things', 'Internet version 2.0', 'Semantic Web', 'Intelligent Web', 'A', 'Internet of Things (IoT) menghubungkan berbagai mesin, perangkat fisik, dan sensor melalui protokol internet untuk pemantauan dan pengendalian jarak jauh.', 1),
  ('q-stsi4207-m1-tf2-09', 'set-stsi4207-m1-3', 'Kemampuan untuk menemukan keterkaitan antara data yang nampak tidak saling berhubungan merupakan kelebihan dari teknologi ....', 'Google SEO', 'Big Data', 'Business Reengineering', 'Business Rendering', 'B', 'Teknologi Big Data Analytics memiliki kemampuan menganalisis kumpulan data masif tak terstruktur guna menemukan pola dan relasi tersembunyi.', 1),
  ('q-stsi4207-m1-tf2-10', 'set-stsi4207-m1-3', 'BRI membeli dan mengoperasikan sendiri satelit telekomunikasi dengan tujuan untuk mengatasi masalah ....', 'jaringan telekomunikasi', 'distribusi dana nasabah', 'kredit macet', 'fraud perbankan', 'A', 'Satelit BRIsat diluncurkan untuk menjamin ketersediaan infrastruktur jaringan telekomunikasi perbankan di ribuan pulau seluruh pelosok Indonesia.', 1),
  ('q-stsi4207-m1-tf3-01', 'set-stsi4207-m1-3', 'Pendekatan yang menggunakan dasar ilmu teknik adalah ....', 'hard approach', 'soft approach', 'technical approach', 'social approach', 'A', 'Hard approach menekankan aspek teknis, model matematis, dan kapabilitas fisik teknologi dalam studi sistem informasi.', 1),
  ('q-stsi4207-m1-tf3-02', 'set-stsi4207-m1-3', 'Pendekatan yang berfokus pada aspek perilaku para pengguna sistem informasi adalah ....', 'hard approach', 'soft approach', 'technical approach', 'social approach', 'B', 'Soft approach (pendekatan perilaku) mengkaji respons psikologis, budaya kerja, dan penerimaan pengguna terhadap sistem informasi.', 1),
  ('q-stsi4207-m1-tf3-03', 'set-stsi4207-m1-3', 'Pendekatan yang menggabungkan pendekatan teknis dan perilaku adalah ....', 'hard approach', 'soft approach', 'technical approach', 'socio-technical approach', 'D', 'Socio-technical approach menyatukan kinerja optimal teknologi dengan kapasitas perilaku manusia dan struktur organisasi.', 1),
  ('q-stsi4207-m1-tf3-04', 'set-stsi4207-m1-3', 'Ilmu yang mempelajari dasar matematis teknologi informasi adalah ilmu ....', 'aljabar', 'rekayasa', 'matematika Dasar', 'komputer', 'D', 'Ilmu komputer (Computer Science) mendalami teori komputabilitas, logika algoritma, dan dasar matematis komputasi.', 1),
  ('q-stsi4207-m1-tf3-05', 'set-stsi4207-m1-3', 'Ilmu yang mempelajari cara pembuatan keputusan manajerial secara ilmiah adalah ....', 'manajemen operasional', 'manajemen sains', 'manajemen keuangan', 'manajemen strategis', 'B', 'Manajemen sains (Management Science) menerapkan metode kuantitatif dan pemodelan matematis untuk pengambilan keputusan manajerial.', 1)
INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m1-tf3-06', 'set-stsi4207-m1-3', 'Ilmu yang mempelajari perilaku individu dalam menggunakan sebuah sistem informasi adalah ....', 'psikologi', 'para Psikologi', 'kognisi', 'meta Kognisi', 'A', 'Psikologi mengkaji proses kognitif, kebiasaan, dan faktor perilaku individu dalam berinteraksi dengan sistem teknologi.', 1),
  ('q-stsi4207-m1-tf3-07', 'set-stsi4207-m1-3', 'Jika kita mempelajari dampak gawai terhadap suasana kerja, maka kita menggunakan dasar ilmu ....', 'sosiatri', 'antropologi', 'sosiologi', 'ekonomi', 'C', 'Sosiologi mempelajari dinamika interaksi sosial, hubungan antarmanusia, dan budaya kelompok dalam lingkungan kerja.', 1),
  ('q-stsi4207-m1-tf3-08', 'set-stsi4207-m1-3', 'Jika kita menghitung harga jual paket berlangganan streaming layanan musik seperti Spotify dan Joox, maka kita menggunakan dasar ilmu ....', 'sosiatri', 'antropologi', 'sosiologi', 'ekonomi', 'D', 'Penentuan struktur harga, elastisitas permintaan, dan monetisasi layanan digital merupakan penerapan ilmu ekonomi.', 1),
  ('q-stsi4207-m1-tf3-09', 'set-stsi4207-m1-3', 'Menunda penggunaan gawai terbaru di suatu perusahaan karena menunggu pelatihan karyawan merupakan contoh penggunaan pendekatan ....', 'hard approach', 'soft approach', 'technical approach', 'socio-technical approach', 'D', 'Menyelaraskan kematangan sumber daya manusia dengan kesiapan teknologi baru merupakan inti dari pendekatan sosio-teknis.', 1),
  ('q-stsi4207-m1-tf3-10', 'set-stsi4207-m1-3', 'Menghitung pendayagunaan fasilitas komputasi perusahaan secara optimal merupakan fokus bidang ilmu .....', 'manajemen operasional', 'operations research', 'manajemen keuangan', 'manajemen strategis', 'B', 'Operations Research (Riset Operasi) berfokus pada optimasi sistematis alokasi sumber daya dan kapasitas komputasi organisasi.', 1),
  ('q-stsi4207-m2-tf1-01', 'set-stsi4207-m1-3', 'Menerima pesanan dari konsumen merupakan proses bisnis dalam fungsi ....', 'penjualan dan pemasaran', 'akuntansi dan keuangan', 'produksi dan manufaktur', 'sumber daya manusia', 'A', 'Penerimaan pesanan dan pelayanan order pembeli merupakan tanggung jawab utama fungsi penjualan dan pemasaran.', 1),
  ('q-stsi4207-m2-tf1-02', 'set-stsi4207-m1-3', 'Berdagang melalui internet disebut sebagai aktivitas ....', 'E-Government', 'E-Catalogue', 'E-Procurement', 'E-Commerce', 'D', 'E-Commerce (Electronic Commerce) adalah aktivitas transaksi jual-beli barang atau jasa secara daring via internet.', 1),
  ('q-stsi4207-m2-tf1-03', 'set-stsi4207-m1-3', 'Penggunaan E-Business untuk bertransaksi antara pemerintah dengan penyedia jasa konstruksi masuk ke dalam kategori ....', 'E-Business', 'E-Government', 'E-Voting', 'E-Commerce', 'B', 'Transaksi digital antara institusi pemerintah dengan pelaku usaha (Government-to-Business / G2B) merupakan domain E-Government.', 1),
  ('q-stsi4207-m2-tf1-04', 'set-stsi4207-m1-3', 'Perangkat teknologi informasi yang berguna untuk membantu kolaborasi antara lain adalah ....', 'ERP', 'ECM', 'Email', 'E-Catalogue', 'C', 'Surel (Email) adalah sarana komunikasi digital fundamental yang memfasilitasi pertukaran pesan dan kolaborasi antarpihak.', 1),
  ('q-stsi4207-m2-tf1-05', 'set-stsi4207-m1-3', 'Orang yang bertanggung jawab untuk membuat aplikasi adalah ....', 'programmer', 'controller', 'systems administrator', 'designer', 'A', 'Programmer bertugas menulis kode sumber program dan membangun fungsionalitas aplikasi komputer.', 1),
  ('q-stsi4207-m2-tf1-06', 'set-stsi4207-m1-3', 'Bekerja sama dengan orang lain untuk mencapai tujuan bersama merupakan definisi dari ....', 'kolaborasi', 'koordinasi', 'kooperasi', 'kooptasi', 'A', 'Kolaborasi adalah proses bekerja bersama antarindividu atau tim secara sinergis demi meraih tujuan yang telah disepakati.', 1),
  ('q-stsi4207-m2-tf1-07', 'set-stsi4207-m1-3', 'Sistem yang digunakan untuk mengelola pengetahuan dalam perusahaan disebut ....', 'knowledge sharing', 'knowledge management systems', 'knowledge distribution', 'knowledge factory', 'B', 'Knowledge Management Systems (KMS) mendukung proses penciptaan, pengorganisasian, penyimpanan, dan penyebaran pengetahuan korporat.', 1),
  ('q-stsi4207-m2-tf1-08', 'set-stsi4207-m1-3', 'Sistem informasi fungsional yang tidak terintegrasi akan menciptakan fenomena ....', 'disfungsonalisasi informasi', 'disintegrasi informasi', 'silo informasi', 'disintermediasi informasi', 'C', 'Information Silo terjadi saat departemen menyimpan datanya secara eksklusif dan terpisah tanpa integrasi lintas divisi.', 1),
  ('q-stsi4207-m2-tf1-09', 'set-stsi4207-m1-3', 'Sistem yang dirancang untuk membantu pembuatan keputusan semi terstruktur dan non rutin adalah ....', 'sistem digital', 'sistem pembuat keputusan', 'sistem pendukung keputusan', 'sistem evaluasi keputusan', 'C', 'Decision Support System (DSS) dirancang untuk membantu para pengambil keputusan menangani permasalahan semi-terstruktur dan masalah tak terduga.', 1),
  ('q-stsi4207-m2-tf1-10', 'set-stsi4207-m1-3', 'Proses bisnis dapat diperbaiki dan ditingkatkan dengan bantuan teknologi informasi melalui cara berikut ini, kecuali ....', 'otomatisasi proses bisnis', 'efisiensi proses bisnis', 'rekayasa ulang proses bisnis', 'birokrasi proses bisnis', 'D', 'TI bertujuan mempermudah dan mempercepat alur kerja; memperpanjang birokrasi justru bertentangan dengan tujuan implementasi TI.', 1),
  ('q-stsi4207-m2-tf2-01', 'set-stsi4207-m1-3', 'Beragam pandangan yang berbeda mengenai pendayagunaan sumber daya organisasi disebut ....', 'budaya organisasi', 'politik organisasi', 'struktur organisasi', 'hirarkir organisasi', 'B', 'Politik organisasi timbul akibat perbedaan kepentingan dan pandangan anggota dalam memperebutkan alokasi sumber daya.', 1),
  ('q-stsi4207-m2-tf2-02', 'set-stsi4207-m1-3', 'Yang tidak termasuk faktor yang mempengaruhi interaksi teknologi informasi dengan organisasi adalah ....', 'keputusan manajemen operasional', 'struktur organisasi', 'politik organisasi', 'budaya organisasi', 'A', 'Faktor penentu interaksi TI berskala makro seperti struktur, budaya, lingkungan, dan politik organisasi; bukan rutinitas operasional kasual.', 1),
  ('q-stsi4207-m2-tf2-03', 'set-stsi4207-m1-3', 'Pernyataan berikut yang tidak benar adalah ....', 'teknologi informasi meminimalkan biaya', 'teknologi informasi meningkatkan efisiensi', 'teknologi informasi memperbesar nilai perusahaan', 'teknologi informasi mengurangi biaya transaksi', 'C', 'TI adalah pemampu (enabler) efisiensi dan penekan biaya; nilai pasar perusahaan ditentukan oleh performa bisnis dan persepsi investor, bukan otomatis membesar hanya karena membeli TI.', 1),
  ('q-stsi4207-m2-tf2-04', 'set-stsi4207-m1-3', 'Yang tidak termasuk kekuatan persaingan menurut Model Porter adalah ....', 'pemasok', 'pemain baru', 'pelanggan', 'lingkungan sekitar', 'D', 'Lima Kekuatan Porter meliputi: Pesaing Industri, Pendatang Baru, Produk Pengganti, Daya Tawar Pemasok, dan Daya Tawar Pembeli.', 1),
  ('q-stsi4207-m2-tf2-05', 'set-stsi4207-m1-3', 'Dalam strategi jaringan, nilai suatu perusahaan dan produknya akan naik jika ....', 'semakin banyak fiturnya', 'semakin banyak penggunanya', 'berkurang masalahnya', 'berkurang kualitasnya', 'B', 'Efek Jaringan (Network Effect) menerangkan bahwa nilai utilitas suatu platform berbanding lurus dengan peningkatan jumlah penggunanya.', 1),
  ('q-stsi4207-m2-tf2-06', 'set-stsi4207-m1-3', 'Yang tidak termasuk aktivitas pendukung dalam model rantai nilai bisnis adalah ....', 'manajemen', 'administrasi', 'pengadaan barang dan jasa', 'layanan purna jual', 'D', 'Layanan purna jual (customer service) adalah aktivitas primer (primary activity), bukan aktivitas pendukung (support activity).', 1),
  ('q-stsi4207-m2-tf2-07', 'set-stsi4207-m1-3', 'Yang bukan termasuk strategi generik menghadapi persaingan menurut Porter adalah ....', 'biaya paling optimal', 'biaya terendah', 'diferensiasi produk', 'fokus pada ceruk pasar', 'A', 'Tiga strategi generik Porter: Keunggulan Biaya Terendah (Low-cost leadership), Diferensiasi Produk, dan Fokus pada Ceruk Pasar (Focus).', 1),
  ('q-stsi4207-m2-tf2-08', 'set-stsi4207-m1-3', 'Kemampuan memenangkan persaingan merupakan dampak dari adanya keunggulan ....', 'teknis', 'bisnis', 'kompetitif', 'informasi', 'C', 'Keunggulan kompetitif (competitive advantage) memungkinkan perusahaan menghasilkan nilai unggul dan mengungguli para pesaingnya.', 1),
  ('q-stsi4207-m2-tf2-09', 'set-stsi4207-m1-3', 'Gojek menawarkan layanan GoRide, GoFood, GoSend, dan GoPay dalam satu aplikasi adalah upaya untuk menang bersaing dengan cara ....', 'biaya terendah', 'diferensiasi produk', 'fokus pada ceruk pasar', 'memperkuat hubungan dengan pemasok', 'B', 'Mengembangkan aplikasi super (Super App) dengan beragam layanan komprehensif adalah strategi diferensiasi produk.', 1),
  ('q-stsi4207-m2-tf2-10', 'set-stsi4207-m1-3', 'Penggunaan sensor dan telekomunikasi data pada barang disebut ....', 'internet 2.0', 'internet of things', 'internet wireless', 'internet superhighway', 'B', 'Internet of Things (IoT) menyematkan sensor cerdas dan transmisi data pada benda fisik agar terkoneksi jaringan.', 1)
INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m3-tf1-01', 'set-stsi4207-m1-3', 'Yang termasuk area abu-abu secara legal yang diakibatkan adanya sistem informasi baru adalah ....', 'sulitnya mengendalikan data', 'belum diatur dengan undang-undang atau regulasi yang ada', 'diimplementasikan secara sembrono', 'tidak memperhatikan kepentingan pengguna tertentu', 'B', 'Inovasi teknologi digital sering bergerak lebih cepat daripada hukum tertulis, sehingga memunculkan area abu-abu regulasi.', 1),
  ('q-stsi4207-m3-tf1-02', 'set-stsi4207-m1-3', 'Pembajakan perangkat lunak masuk ke wilayah dimensi moral ....', 'hak dan kewajiban kepemilikan', 'kualitas sistem', 'kualitas hidup', 'hak dan kewajiban informasi', 'A', 'Pembajakan software melanggar hak cipta dan perlindungan kekayaan intelektual (Property Rights and Obligations).', 1),
  ('q-stsi4207-m3-tf1-03', 'set-stsi4207-m1-3', 'Siap menanggung potensi kerugian atas keputusan yang dibuat disebut ....', 'liabilitas', 'proses hukum', 'akuntabilitas', 'tanggung jawab', 'D', 'Tanggung jawab (responsibility) adalah kesediaan moral individu untuk menerima konsekuensi atas keputusan yang diambilnya.', 1),
  ('q-stsi4207-m3-tf1-04', 'set-stsi4207-m1-3', 'Mekanisme yang menentukan siapa yang bertindak dan siapa yang bertanggung jawab atas suatu tindakan disebut ....', 'liabilitas', 'proses hukum', 'akuntabilitas', 'tanggung jawab', 'C', 'Akuntabilitas (accountability) merupakan mekanisme penelusuran untuk menentukan pihak yang bertanggung jawab atas pelaksanaan suatu tindakan.', 1),
  ('q-stsi4207-m3-tf1-05', 'set-stsi4207-m1-3', 'Aturan yang memungkinkan orang yang dirugikan oleh suatu tindakan (baik oleh individu, sistem, maupun organisasi) untuk mendapatkan kompensasi yang layak disebut ....', 'liabilitas', 'proses hukum', 'akuntabilitas', 'tanggung jawab', 'A', 'Liabilitas (liability) merupakan ketentuan hukum yang memberi hak bagi pihak terzalimi/dirugikan untuk menuntut kompensasi atau pemulihan.', 1),
  ('q-stsi4207-m3-tf1-06', 'set-stsi4207-m1-3', 'Seseorang mencuri makanan dari supermarket karena keluarganya kelaparan, jika dievaluasi dengan Utilitarian Principle maka ....', 'dapat diterima karena pemilik supermarket kaya', 'dapat diterima karena menyelamatkan keluarga dari kelaparan', 'salah karena tidak ada orang yang mau dicuri barangnya', 'salah karena mencuri itu salah untuk semua orang', 'B', 'Prinsip Utilitarian menilai tindakan berdasarkan manfaat atau pencegahan mudarat terbesar yang dihasilkan (menyelamatkan nyawa keluarga dari kelaparan).', 1),
  ('q-stsi4207-m3-tf1-07', 'set-stsi4207-m1-3', 'Edward Snowden membocorkan data bahwa pemerintah Amerika Serikat memata-matai warganya, menurut Golden Rule maka tindakan tersebut ....', 'dapat diterima untuk kepentingan publik', 'salah karena melanggar hukum', 'tidak dapat diterima, tidak ada yang mau dimata-matai', 'netral', 'C', 'Aturan Emas (Golden Rule) menyatakan jangan memperlakukan orang lain seperti halnya Anda tidak ingin diperlakukan (tidak ada yang suka dimata-matai).', 1),
  ('q-stsi4207-m3-tf1-08', 'set-stsi4207-m1-3', 'Mengedarkan lagu yang disalin dari komputer teman termasuk dalam dimensi moral ....', 'hak dan kewajiban kepemilikan', 'kualitas sistem', 'kualitas hidup', 'hak dan kewajiban informasi', 'A', 'Menyalin dan menyebarkan karya hak cipta tanpa izin menyangkut hak kepemilikan kekayaan intelektual (Property Rights).', 1),
  ('q-stsi4207-m3-tf1-09', 'set-stsi4207-m1-3', 'Seorang teknisi salah memasang perangkat yang membuat sistem perbankan macet dan merugikan nasabah termasuk dalam dimensi moral ....', 'hak dan kewajiban kepemilikan', 'kualitas sistem', 'kualitas hidup', 'hak dan kewajiban informasi', 'B', 'Kualitas sistem (System Quality) mengatur standar keandalan perangkat dan tanggung jawab atas kesalahan operasional perangkat lunak/keras.', 1),
  ('q-stsi4207-m3-tf1-10', 'set-stsi4207-m1-3', 'Di negara Uni Eropa, pengguna dapat meminta Google menghapus catatan penggunaan miliknya, hal ini termasuk dalam dimensi moral ....', 'hak dan kewajiban kepemilikan', 'kualitas sistem', 'kualitas hidup', 'hak dan kewajiban informasi', 'D', 'Hak atas privasi data pribadi dan ''right to be forgotten'' termasuk ke dalam dimensi Hak dan Kewajiban Informasi (Information Rights).', 1),
  ('q-stsi4207-m3-tf2-01', 'set-stsi4207-m1-3', 'Model penggunaan data pribadi di mana diasumsikan pemilik data mengizinkan kecuali dinyatakan secara eksplisit disebut ....', 'opt in', 'opt out', 'opt off', 'opt send', 'B', 'Opt-out mengasumsikan data pribadi boleh dikumpulkan secara default kecuali pengguna mengambil tindakan tegas untuk menolaknya.', 1),
  ('q-stsi4207-m3-tf2-02', 'set-stsi4207-m1-3', 'Model penggunaan data pribadi di mana diasumsikan pemilik data tidak mengizinkan kecuali dinyatakan secara eksplisit disebut ....', 'opt in', 'opt out', 'opt off', 'opt send', 'A', 'Opt-in mewajibkan perusahaan meminta izin secara eksplisit terlebih dahulu sebelum data konsumen boleh direkam dan digunakan.', 1),
  ('q-stsi4207-m3-tf2-03', 'set-stsi4207-m1-3', 'File kecil yang ditanamkan oleh suatu situs web ke perangkat milik pengunjungnya disebut ....', 'bread crumb', 'biscuit', 'cookies', 'cookout', 'C', 'Cookies adalah berkas teks kecil yang dikirim server web ke browser klien guna menyimpan riwayat kunjungan dan preferensi.', 1),
  ('q-stsi4207-m3-tf2-04', 'set-stsi4207-m1-3', 'Perlindungan terhadap buku pelajaran teknik sipil adalah ....', 'hak paten', 'hak cipta', 'hak milik', 'hak guna', 'B', 'Karya tulis, literatur, dan buku teks dilindungi di bawah hukum Hak Cipta (Copyright).', 1),
  ('q-stsi4207-m3-tf2-05', 'set-stsi4207-m1-3', 'Perlindungan terhadap resep rahasia produk minuman adalah ....', 'merek dagang', 'hak cipta', 'hak paten', 'rahasia dagang', 'D', 'Formula resep makanan/minuman yang dirahasiakan dilindungi secara hukum melalui instrumen Rahasia Dagang (Trade Secret).', 1),
  ('q-stsi4207-m3-tf2-06', 'set-stsi4207-m1-3', 'Perlindungan terhadap teknologi komunikasi 4G/LTE adalah ....', 'merk dagang', 'hak cipta', 'hak paten', 'rahasia dagang', 'C', 'Invensi proses dan teknologi perangkat keras baru seperti modul 4G/LTE dilindungi dengan Hak Paten.', 1),
  ('q-stsi4207-m3-tf2-07', 'set-stsi4207-m1-3', 'Yang bukan merupakan sumber energi baru terbarukan adalah Pembangkit listrik ....', 'tenaga surya', 'tenaga gelombang', 'tenaga uap', 'tenaga angin', 'C', 'PLTU memanfaatkan batu bara atau minyak (bahan bakar fosil yang tidak terbarukan).', 1),
  ('q-stsi4207-m3-tf2-08', 'set-stsi4207-m1-3', 'Energi listrik pada pusat data milik perusahaan besar teknologi informasi dunia digunakan untuk mengoperasikan dan mendinginkan ....', 'generator', 'perangkat komputer', 'perangkat pembangkit daya', 'perangkat lunak', 'B', 'Daya listrik terbesar di fasilitas data center terserap untuk memberi daya dan mendinginkan rak server perangkat komputer.', 1),
  ('q-stsi4207-m3-tf2-09', 'set-stsi4207-m1-3', 'Bahan beracun dan berbahaya di bawah ini yang tidak digunakan untuk membuat perangkat keras komputer adalah ....', 'cadmium', 'merkurium', 'arsenikum', 'radium', 'D', 'Radium merupakan isotop radioaktif dan tidak digunakan dalam jalur perakitan sirkuit perangkat keras komputer umum.', 1),
  ('q-stsi4207-m3-tf2-10', 'set-stsi4207-m1-3', 'Menggunakan papan kunci dan tetikus secara terus-menerus berkontribusi pada kondisi yang disebut ....', 'repetitive sin innocents', 'repetitive stress disorder', 'repetitive post traumatic', 'repetitive stress injury', 'D', 'RSI (Repetitive Stress Injury) terjadi karena kelelahan jaringan otot akibat gerakan repetitif pada keyboard dan mouse.', 1),
  ('q-stsi4207-m4-tf1-01', 'set-stsi4207-m4-6', 'SAN adalah ....', 'storage area network', 'storage attached network', 'storage array network', 'storage access network', 'A', 'SAN adalah Storage Area Network, yaitu jaringan berkecepatan tinggi khusus menghubungkan server ke sistem media penyimpanan data.', 1),
  ('q-stsi4207-m4-tf1-02', 'set-stsi4207-m4-6', 'Antar muka yang menggunakan layar pada perangkat adalah ....', 'stylus', 'touch Screen', 'touch Pen', 'digitizer', 'B', 'Touch Screen (layar sentuh) memungkinkan interaksi input langsung pengguna melalui sentuhan pada permukaan layar.', 1),
  ('q-stsi4207-m4-tf1-03', 'set-stsi4207-m4-6', 'Bahasa Pemrograman yang dapat dijalankan pada berbagai perangkat adalah ....', 'C++', 'Assembler', 'Pascal', 'Java', 'D', 'Bahasa pemrograman Java memiliki arsitektur portabel berbasis JVM dengan prinsip ''Write Once, Run Anywhere'' (WORA).', 1),
  ('q-stsi4207-m4-tf1-04', 'set-stsi4207-m4-6', 'Ciri khas aplikasi dengan lisensi kode terbuka adalah ....', 'gratis dan boleh dijual', 'gratis dan kode sumber disediakan', 'berbayar dan terbatas', 'berbayar dan boleh digandakan', 'B', 'Open Source Software menyediakan source code secara terbuka sehingga bebas ditelaah, diubah, dan didistribusikan.', 1),
  ('q-stsi4207-m4-tf1-05', 'set-stsi4207-m4-6', 'Menurut hukum Moore, kekuatan komputasi akan naik dua kali lipat setiap ....', '18 bulan', '18 tahun', '18 minggu', '18 hari', 'A', 'Hukum Moore menyatakan kerapatan transistor pada sirkuit terpadu mikroprosesor berlipat ganda kira-kira setiap 18 bulan.', 1)
INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m4-tf1-06', 'set-stsi4207-m4-6', 'Kelebihan komputer kuantum dibanding komputer biasa adalah dapat ....', 'bekerja sangat lama', 'mengolah data 1 atau 0', 'bekerja lebih sunyi', 'mengolah data 1,0, dan keduanya secara simultan', 'D', 'Qubit dalam komputasi kuantum dapat berada dalam keadaan superposisi, merepresentasikan nilai 0, 1, atau keduanya sekaligus.', 1),
  ('q-stsi4207-m4-tf1-07', 'set-stsi4207-m4-6', 'Jenis komputer yang digunakan untuk menangani transaksi penting perbankan karena keandalannya adalah ....', 'blade server', 'rack server', 'mainframe', 'tablet', 'C', 'Mainframe digunakan oleh institusi keuangan untuk memproses jutaan transaksi simultan dengan reliabilitas dan keamanan tingkat tinggi.', 1),
  ('q-stsi4207-m4-tf1-08', 'set-stsi4207-m4-6', 'Aplikasi yang biasa digunakan untuk mengakses layanan komputasi awan adalah ....', 'browser', 'FTP client', 'word processor', 'defrager', 'A', 'Web browser merupakan aplikasi utama di sisi klien yang digunakan untuk berinteraksi dengan layanan cloud computing.', 1),
  ('q-stsi4207-m4-tf1-09', 'set-stsi4207-m4-6', 'Kebijakan untuk memperbolehkan penggunaan perangkat pribadi untuk kepentingan kerja disebut ....', 'BYOB', 'BYOD', 'BSOD', 'MYOB', 'B', 'BYOD (Bring Your Own Device) adalah kebijakan perusahaan yang memperkenankan karyawan bekerja memakai gawai milik pribadi.', 1),
  ('q-stsi4207-m4-tf1-10', 'set-stsi4207-m4-6', 'Sistem operasi perangkat bergerak yang dominan saat ini adalah ....', 'Android dan iOS', 'Symbian dan Blackberry', 'MS Windows CE dan Android', 'iOS dan FreeBSD', 'A', 'Android (Google) dan iOS (Apple) menguasai lebih dari 99% pangsa pasar sistem operasi mobile dunia saat ini.', 1),
  ('q-stsi4207-m4-tf2-01', 'set-stsi4207-m4-6', 'Dalam model Package Switching, data yang akan dikirim diperlakukan ....', 'dikirim langsung', 'dijadikan beberapa paket data dan dikirim melalui jalur berbeda', 'dijadikan beberapa paket data dan dikirim bergantian', 'dijadikan beberapa paket data dan dikirim bersamaan', 'B', 'Packet Switching memecah aliran data menjadi potongan paket mandiri yang dapat menempuh rute jaringan yang berbeda.', 1),
  ('q-stsi4207-m4-tf2-02', 'set-stsi4207-m4-6', 'Alat yang menghubungkan sebuah jaringan komputer dengan berbagai jaringan lain yang berbeda adalah ....', 'hub', 'switch', 'repeater', 'router', 'D', 'Router bertugas merutekan paket data antarjaringan komputer dengan subnet IP atau teknologi yang berbeda.', 1),
  ('q-stsi4207-m4-tf2-03', 'set-stsi4207-m4-6', 'Kabel untuk menghubungkan jaringan telekomunikasi antar benua adalah ....', 'fiber glass', 'fiber optic', 'fiber soluble', 'fiber kevlar', 'B', 'Kabel fiber optic laut dalam menghubungkan jaringan telekomunikasi dan internet antarpulau dan antarbenua dengan kecepatan cahaya.', 1),
  ('q-stsi4207-m4-tf2-04', 'set-stsi4207-m4-6', 'Alat telekomunikasi yang dapat menjangkau sepertiga permukaan bumi adalah ....', 'Satelit', 'Wifi', 'BTS', 'Bluetooth', 'A', 'Satu unit satelit geostasioner pada ketinggian 36.000 km di atas khatulistiwa dapat memancarkan sinyal mencakup sepertiga belahan bumi.', 1),
  ('q-stsi4207-m4-tf2-05', 'set-stsi4207-m4-6', 'Perangkat pengeras suara komputer tanpa kabel termasuk jaringan ....', 'WAN', 'WLAN', 'LAN', 'PAN', 'B', 'Speaker nirkabel yang terhubung ke jaringan tanpa kabel lokal termasuk kategori jaringan nirkabel (Wireless LAN / PAN).', 1),
  ('q-stsi4207-m4-tf2-06', 'set-stsi4207-m4-6', 'Badan yang mengelola alokasi nama domain dan alamat IP adalah ....', 'ICANN', 'WTO', 'W3C', 'IMF', 'A', 'ICANN (Internet Corporation for Assigned Names and Numbers) adalah lembaga internasional yang mengkoordinasikan alamat IP dan Domain Name System (DNS).', 1),
  ('q-stsi4207-m4-tf2-07', 'set-stsi4207-m4-6', 'Alamat IP yang terdiri atas 4 blok angka antara 0-255 adalah versi ....', '1', '2', '4', '6', 'C', 'IPv4 terdiri atas 4 oktet angka 8-bit berkisar dari 0 sampai 255 (misal: 192.168.1.1).', 1),
  ('q-stsi4207-m4-tf2-08', 'set-stsi4207-m4-6', 'Energi listrik pada pusat data milik perusahaan besar teknologi informasi dunia digunakan untuk mengoperasikan dan mendinginkan ....', 'generator', 'perangkat komputer', 'perangkat pembangkit daya', 'perangkat lunak', 'B', 'Kebutuhan listrik fasilitas data center terutama difokuskan untuk menjalankan prosesor dan sistem pendingin server komputer.', 1),
  ('q-stsi4207-m4-tf2-09', 'set-stsi4207-m4-6', 'Layanan telepon menggunakan jalur Internet adalah ....', 'VOIP', 'VOLTE', 'VOLTA', 'MIRC', 'A', 'VoIP (Voice over Internet Protocol) memungkinkan transmisi panggilan suara secara digital melalui jaringan internet.', 1),
  ('q-stsi4207-m4-tf2-10', 'set-stsi4207-m4-6', 'Server Internet yang melayani permintaan dokumen dari klien adalah ....', 'web server', 'file server', 'application server', 'database server', 'A', 'Web server melayani permintaan berkas dokumen web (HTML, CSS, gambar) yang diminta oleh peramban (browser) klien.', 1),
  ('q-stsi4207-m5-tf1-01', 'set-stsi4207-m4-6', 'Malware yang membajak komputer korban dan menuntut tebusan untuk melepaskannya adalah ....', 'virus', 'worms', 'adware', 'ransomware', 'D', 'Ransomware mengenkripsi dokumen penting korban dan memeras korban dengan tebusan finansial untuk mendapatkan kunci dekripsi.', 1),
  ('q-stsi4207-m5-tf1-02', 'set-stsi4207-m4-6', 'Upaya melumpuhkan sistem kelistrikan suatu negara oleh aparat negara lain disebut ....', 'peperangan siber', 'terorisme siber', 'sibernetics', 'kejahatan komputer', 'A', 'Peperangan siber (cyberwarfare) melibatkan serangan digital tersponsori negara untuk merusak infrastruktur krusial negara lawan.', 1),
  ('q-stsi4207-m5-tf1-03', 'set-stsi4207-m4-6', 'Program khusus yang secara mandiri menggandakan dirinya sendiri dari satu komputer ke komputer lain melalui jaringan komputer disebut ....', 'virus', 'worms', 'adware', 'ransomware', 'B', 'Worm menyebar dan menggandakan dirinya secara otonom melalui celah port jaringan tanpa membutuhkan berkas inang manusia.', 1),
  ('q-stsi4207-m5-tf1-04', 'set-stsi4207-m4-6', 'Kerapuhan perangkat lunak yang belum diketahui oleh yang berkepentingan (pembuat dan pengguna) sehingga tidak dilakukan tindakan mitigasi disebut ....', 'bugs', 'error', 'zero day vulnerabilities', 'inherent vulnerabilities', 'C', 'Zero-Day Vulnerability adalah celah keamanan baru yang belum sempat ditambal oleh pengembang peranti lunak.', 1),
  ('q-stsi4207-m5-tf1-05', 'set-stsi4207-m4-6', 'Malware yang dirancang untuk menyerang komputer pengendali mesin industri adalah ....', 'stoned', 'wanna cry', 'stuxnet', 'petya', 'C', 'Stuxnet adalah worm siber canggih yang secara spesifik menargetkan Programmable Logic Controller (PLC) sistem industri SCADA.', 1),
  ('q-stsi4207-m5-tf1-06', 'set-stsi4207-m4-6', 'Kejahatan dengan menggunakan akses poin wifi palsu yang seolah-olah sebagai penyedia layanan akses wifi yang terpercaya untuk mencuri data disebut ....', 'evil twins', 'wanna cry', 'stuxnet', 'petya', 'A', 'Evil Twin adalah access point rogue nakal yang meniru nama SSID terpercaya demi mencuri kredensial korban yang login.', 1),
  ('q-stsi4207-m5-tf1-07', 'set-stsi4207-m4-6', 'Wifi dianggap kurang aman, karena ....', 'mudah dipakai', 'sering crash', 'mudah disadap', 'lambat', 'C', 'Sinyal radio Wi-Fi memancar bebas melintasi dinding sehingga lebih rentan disadap atau diintersepsi gelombangnya.', 1),
  ('q-stsi4207-m5-tf1-08', 'set-stsi4207-m4-6', 'Pembaharuan perangkat lunak untuk menutup celah keamanan disebut sebagai ....', 'patch', 'compiler', 'interpreter', 'cache', 'A', 'Patch keamanan dirilis produsen untuk menambal bug serta menutup celah eksploitasi kode pada aplikasi.', 1),
  ('q-stsi4207-m5-tf1-09', 'set-stsi4207-m4-6', 'Bujukan dan tipu daya kepada seseorang untuk memberikan akun dan password disebut sebagai ....', 'evil twins', 'social network', 'stuxnet', 'social engineering', 'D', 'Social Engineering mengandalkan manipulasi psikologis agar korban secara sukarela membocorkan kata sandi atau data rahasia.', 1),
  ('q-stsi4207-m5-tf1-10', 'set-stsi4207-m4-6', 'Membanjiri server yang dituju dengan permintaan atas data yang berlebihan sehingga diharapkan server yang dituju kewalahan dan berhenti bekerja disebut sebagai ....', 'MS DOS', 'PC DOS', 'DOS', 'DR DOS', 'C', 'DoS (Denial of Service) melumpuhkan ketersediaan server dengan membanjiri antrean paket request secara masif.', 1)
INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m5-tf2-01', 'set-stsi4207-m4-6', 'Kerahasiaan rekam medis pasien dilindungi oleh regulasi ....', 'Peraturan Menteri Kesehatan Nomor 269 Tahun 2008', 'Peraturan Menteri PAN RB Nomor 269 Tahun 2008', 'UU Nomor 5 Tahun 2011', 'UU Nomor 19 Tahun 2006', 'A', 'Permenkes No. 269/MENKES/PER/III/2008 adalah regulasi yang mengatur standar pengelolaan dan kerahasiaan rekam medis di Indonesia.', 1),
  ('q-stsi4207-m5-tf2-02', 'set-stsi4207-m4-6', 'Menggunakan PIN dan Kartu ATM untuk bertransaksi melalui mesin ATM adalah upaya ....', 'manajemen risiko', 'manajemen identitas', 'manajemen laba', 'manajemen sumber daya', 'B', 'Penerapan autentikasi kartu dan PIN adalah pilar manajemen identitas (Identity Management) untuk memastikan keabsahan pengguna.', 1),
  ('q-stsi4207-m5-tf2-03', 'set-stsi4207-m4-6', 'Membeli asuransi untuk gedung pusat data termasuk upaya ....', 'manajemen risiko', 'manajemen identitas', 'manajemen laba', 'manajemen sumber daya', 'A', 'Membeli asuransi merupakan strategi pemindahan risiko (risk transference) dalam kerangka manajemen risiko organisasi.', 1),
  ('q-stsi4207-m5-tf2-04', 'set-stsi4207-m4-6', 'Profesi Computer Forensics bertanggung jawab untuk ....', 'merekayasa data', 'memanipulasi gambar', 'menyajikan bukti ke pengadilan', 'menangkap pelaku kejahatan komputer', 'C', 'Spesialis forensik komputer bertugas mengumpulkan, memelihara integritas, dan menyajikan alat bukti digital di muka pengadilan.', 1),
  ('q-stsi4207-m5-tf2-05', 'set-stsi4207-m4-6', 'Konfirmasi rekening tujuan dan jumlah sebelum melakukan transfer dana di ATM merupakan bagian dari ....', 'pengendalian keluaran', 'pengendalian masukan', 'pengendalian proses', 'pengendalian data', 'B', 'Langkah konfirmasi data sebelum transaksi dieksekusi adalah bentuk pengendalian masukan (input control) guna mencegah galat input.', 1),
  ('q-stsi4207-m5-tf2-06', 'set-stsi4207-m4-6', 'PIN kartu ATM diberikan kepada nasabah menggunakan amplop tertutup dan tersegel adalah upaya dari ....', 'pengendalian keluaran', 'pengendalian masukan', 'pengendalian proses', 'pengendalian data', 'A', 'Penyampaian dokumen cetak rahasia kepada nasabah dalam amplop segel merupakan bagian dari pengendalian keluaran (output control).', 1),
  ('q-stsi4207-m5-tf2-07', 'set-stsi4207-m4-6', 'Pintu ruang komputer dikunci dan hanya orang tertentu yang boleh membawa kuncinya adalah contoh dari ....', 'pengendalian keluaran', 'pengendalian masukan', 'pengendalian umum', 'pengendalian aplikasi', 'C', 'Pengendalian fisik fasilitas ruang server komputer merupakan salah satu bentuk pengendalian umum (general controls).', 1),
  ('q-stsi4207-m5-tf2-08', 'set-stsi4207-m4-6', 'Menggunakan genset dan baterai cadangan merupakan upaya ....', 'disaster preparedness', 'disaster mitigation', 'disaster recovery plan', 'disaster crisis', 'C', 'Penyediaan generator listrik dan UPS cadangan merupakan bagian dari rencana pemulihan bencana (Disaster Recovery Plan).', 1),
  ('q-stsi4207-m5-tf2-09', 'set-stsi4207-m4-6', 'Kantor cabang bank di Solo mengambil alih pelayanan nasabah ketika kantor cabang di Yogya terkena bencana merupakan bagian dari ....', 'disaster preparedness', 'disaster mitigation', 'disaster recovery plan', 'business continuity planning', 'D', 'Business Continuity Planning (BCP) memastikan layanan utama bisnis tetap berkesinambungan saat salah satu unit operasional lumpuh.', 1),
  ('q-stsi4207-m5-tf2-10', 'set-stsi4207-m4-6', 'Tujuan audit sistem informasi adalah ...', 'menguji keamanan sistem informasi', 'memeriksa apakah kebijakan keamanan dipatuhi', 'menemukan kesalahan personel sistem informasi', 'menguji kesiapan sistem informasi menghadapi bencana', 'C', 'Audit sistem informasi bertujuan mendeteksi kesalahan pelaksanaan prosedur dan mengevaluasi kepatuhan kontrol internal staf sistem informasi.', 1),
  ('q-stsi4207-m6-tf1-01', 'set-stsi4207-m4-6', 'Kumpulan bit disebut ....', 'byte', 'binary digit', 'bite', 'bittermen', 'A', 'Satu Byte dibentuk oleh gabungan 8 bit data biner.', 1),
  ('q-stsi4207-m6-tf1-02', 'set-stsi4207-m4-6', 'Data yang sama disimpan di beberapa tempat disebut sebagai ....', 'recycle', 'redundancy', 'reuse', 'register', 'B', 'Redundansi data (data redundancy) adalah duplikasi data identik yang tersimpan secara berulang pada lokasi berkas yang berbeda.', 1),
  ('q-stsi4207-m6-tf1-03', 'set-stsi4207-m4-6', 'Sesuatu yang datanya akan direkam dan disimpan oleh suatu organisasi disebut ....', 'ekuitas', 'aset', 'equilibrium', 'entitas', 'D', 'Entitas (Entity) adalah objek nyata atau konsep (orang, tempat, transaksi) yang informasinya dikumpulkan dan disimpan dalam database.', 1),
  ('q-stsi4207-m6-tf1-04', 'set-stsi4207-m4-6', 'Karakteristik entitas disebut sebagai ....', 'atribut', 'aset', 'ekuitas', 'entitas', 'A', 'Atribut (Attribute) adalah elemen atau kolom yang menerangkan sifat dan karakteristik unik dari suatu entitas.', 1),
  ('q-stsi4207-m6-tf1-05', 'set-stsi4207-m4-6', 'Perangkat lunak untuk mengelola data secara terpusat adalah ....', 'DBMS', 'NTFS', 'APFS', 'SPSS', 'A', 'DBMS (Database Management System) adalah sistem perangkat lunak yang mengatur pembuatan, pemeliharaan, dan akses basis data terpusat.', 1),
  ('q-stsi4207-m6-tf1-06', 'set-stsi4207-m4-6', 'Model basis data yang menggambarkan data sebagai tabel dua dimensi adalah ....', 'relativitas', 'assymetry', 'relasional', 'algoritma', 'C', 'Basis data relasional (Relational Database) menyajikan data dalam bentuk tabel dua dimensi yang terdiri atas baris dan kolom.', 1),
  ('q-stsi4207-m6-tf1-07', 'set-stsi4207-m4-6', 'Bahasa standar untuk memanipulasi dan mengelola basis data adalah ....', 'SQL', 'Python', 'C++', 'Visual Basic', 'A', 'SQL (Structured Query Language) merupakan bahasa standar de facto untuk mendefinisikan dan memanipulasi data dalam basis data relasional.', 1),
  ('q-stsi4207-m6-tf1-08', 'set-stsi4207-m4-6', 'Proses untuk menormalkan suatu relasi dalam basis data dengan memecah satu tabel menjadi beberapa tabel disebut ....', 'optimasi', 'normalisasi', 'deNormalisasi', 'defragmentasi', 'B', 'Normalisasi adalah teknik mendesain skema relasional dengan memecah tabel kompleks guna meminimalkan redundansi data.', 1),
  ('q-stsi4207-m6-tf1-09', 'set-stsi4207-m4-6', 'Basis data khusus untuk mengelola Big Data adalah ....', 'MySQL', 'NoSQL', 'PostgreSQL', 'TransactSQL', 'B', 'Database NoSQL (Not Only SQL) dirancang dengan fleksibilitas tinggi untuk menangani volume data masif tak terstruktur dalam Big Data.', 1),
  ('q-stsi4207-m6-tf1-10', 'set-stsi4207-m4-6', 'Proses memasukkan data dari sistem pengolahan transaksi ke Data Warehouse adalah ....', 'EMT', 'ECT', 'ECM', 'ETL', 'D', 'ETL adalah singkatan dari Extract, Transform, and Load dalam proses migrasi dan integrasi data transaksi ke dalam data warehouse.', 1),
  ('q-stsi4207-m6-tf2-01', 'set-stsi4207-m4-6', 'Agar dapat digunakan secara optimal pengetahuan membutuhkan ....', 'kompetisi', 'koperasi', 'kooptasi', 'kolaborasi', 'D', 'Pemanfaatan pengetahuan organisasi menuntut adanya kolaborasi dan budaya berbagi (knowledge sharing) antarkaryawan.', 1),
  ('q-stsi4207-m6-tf2-02', 'set-stsi4207-m4-6', 'Keterampilan untuk mengukir kayu termasuk pengetahuan ....', 'tacit', 'eksplisit', 'terstruktur', 'tidak terstruktur', 'A', 'Tacit knowledge adalah keahlian personal, intuisi, dan keterampilan motorik yang tersimpan dalam pikiran dan sulit dituangkan dalam dokumen.', 1),
  ('q-stsi4207-m6-tf2-03', 'set-stsi4207-m4-6', 'Kebijakan tertulis mengenai penggunaan laboratorium sebuah universitas merupakan pengetahuan ....', 'tacit', 'eksplisit', 'terstruktur', 'tidak terstruktur', 'B', 'Explicit knowledge adalah pengetahuan yang telah diformalkan dan didokumentasikan secara tertulis sehingga mudah disebarluaskan.', 1),
  ('q-stsi4207-m6-tf2-04', 'set-stsi4207-m4-6', 'Skema untuk membuat klasifikasi pengetahuan disebut ....', 'taksasi', 'taksidermi', 'taksonomi', 'taksaka', 'C', 'Taksonomi pengetahuan adalah struktur pengelompokan hierarkis untuk mengorganisasi dan mengkategorikan informasi.', 1),
  ('q-stsi4207-m6-tf2-05', 'set-stsi4207-m4-6', 'Aplikasi yang banyak digunakan untuk pembelajaran jarak jauh adalah ....', 'LST', 'LCD', 'LMS', 'LED', 'C', 'LMS (Learning Management System) adalah platform software untuk mengelola perkuliahan, modul ajar, dan evaluasi daring.', 1)
INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m6-tf2-06', 'set-stsi4207-m4-6', 'Arsitek rumah biasanya menggunakan aplikasi ....', 'CAD', 'CAM', 'VR', 'Pokemon Go', 'A', 'CAD (Computer-Aided Design) dipakai para arsitek dan teknisi perancang untuk menggambar denah dan visualisasi presisi 2D/3D.', 1),
  ('q-stsi4207-m6-tf2-07', 'set-stsi4207-m4-6', 'Alat simulasi untuk ujian Surat Ijin Mengemudi merupakan contoh dari ....', 'CAD', 'CAM', 'VR', 'Pokemon Go', 'C', 'Virtual Reality (VR) menghadirkan simulasi imersif lingkungan berkendara yang aman dan realistis untuk pelatihan pengemudi.', 1),
  ('q-stsi4207-m6-tf2-08', 'set-stsi4207-m4-6', 'MIT Open Source Ware menggunakan aplikasi ....', 'LST', 'LCD', 'LMS', 'LED', 'C', 'MIT OpenCourseWare menyajikan materi pendidikan terbuka menggunakan platform sistem manajemen pembelajaran (LMS).', 1),
  ('q-stsi4207-m6-tf2-09', 'set-stsi4207-m4-6', 'Manusia membutuhkan bantuan kecerdasan buatan dalam manajemen pengetahuan ....', 'setiap saat', 'tidak pernah', 'datanya tidak ada', 'jumlah data dan informasi sangat besar', 'D', 'Saat volume data sangat masif, algoritma Artificial Intelligence membantu memilah, mengelompokkan, dan menemukan intisari pengetahuan.', 1),
  ('q-stsi4207-m6-tf2-10', 'set-stsi4207-m4-6', 'Pembelajaran organisasi mayoritas melibatkan pengetahuan yang bersifat ....', 'tacit', 'eksplisit', 'terstruktur', 'tidak terstruktur', 'B', 'Pengetahuan eksplisit yang terangkum dalam dokumen standar dan pedoman kerja menjadi sarana utama transfer ilmu di organisasi.', 1),
  ('q-stsi4207-m7-tf1-01', 'set-stsi4207-m7-9', 'Perusahaan besar dengan banyak divisi, usaha berskala besar, dan anak perusahaan disebut ....', 'Enterpreneur', 'Socialpreneur', 'Enterprise', 'Technopreneur', 'C', 'Enterprise adalah istilah korporasi berskala besar dengan berbagai unit bisnis dan jaringan anak perusahaan yang terintegrasi.', 1),
  ('q-stsi4207-m7-tf1-02', 'set-stsi4207-m7-9', 'Dampak dari pembentukan divisi yang saling berdiri sendiri dalam suatu perusahaan besar adalah ....', 'silo informasi', 'kuasi informasi', 'politik organisasi', 'isolasi informasi', 'A', 'Pemisahan divisi tanpa integrasi menciptakan sekat ''silo informasi'', di mana informasi terisolasi dan tidak mengalir ke bagian lain.', 1),
  ('q-stsi4207-m7-tf1-03', 'set-stsi4207-m7-9', 'Proses pengiriman barang merupakan bagian dari modul ERP ....', 'akuntansi dan keuangan', 'manufaktur dan operasi', 'penjualan dan pemasaran', 'sumber daya manusia', 'B', 'Pengelolaan gudang, logistik, dan pengiriman fisik barang diatur dalam modul operasi dan manufaktur (Supply Chain Management).', 1),
  ('q-stsi4207-m7-tf1-04', 'set-stsi4207-m7-9', 'Pengajuan ijin cuti pegawai merupakan bagian dari modul ERP ....', 'akuntansi dan keuangan', 'manufaktur dan operasi', 'penjualan dan pemasaran', 'sumber daya manusia', 'D', 'Pengajuan cuti, absensi, dan data kepegawaian diproses dalam modul Human Resource Management (HRM).', 1),
  ('q-stsi4207-m7-tf1-05', 'set-stsi4207-m7-9', 'Petani tembakau bagi perusahaan rokok merupakan bagian segmen rantai pasokan ....', 'streamer', 'upstream', 'internal', 'downstream', 'B', 'Penyedia bahan baku mentah dasar berada pada bagian hulu (upstream) dalam rantai pasokan (supply chain).', 1),
  ('q-stsi4207-m7-tf1-06', 'set-stsi4207-m7-9', 'Minimarket merupakan bagian rantai pasokan yang masuk dalam segmen ....', 'streamer', 'upstream', 'internal', 'downstream', 'D', 'Toko eceran yang menyalurkan produk jadi langsung kepada konsumen akhir berada pada segmen hilir (downstream).', 1),
  ('q-stsi4207-m7-tf1-07', 'set-stsi4207-m7-9', 'Kegiatan produksi yang dipicu oleh estimasi penjualan disebut ....', 'push manufacturing', 'pull manufacturing', 'modern manufacturing', 'traditional manufacturing', 'A', 'Push-based model memproduksi barang berdasarkan peramalan (forecast) penjualan sebelum pesanan aktual tiba.', 1),
  ('q-stsi4207-m7-tf1-08', 'set-stsi4207-m7-9', 'Modul yang membantu tenaga penjualan dalam perangkat lunak CRM adalah ....', 'SFA', 'PO', 'AR', 'AP', 'A', 'SFA (Sales Force Automation) membantu tenaga penjual mencatat prospek pelanggan, jadwal follow-up, dan riwayat penawaran.', 1),
  ('q-stsi4207-m7-tf1-09', 'set-stsi4207-m7-9', 'Bagian CRM yang menentukan apa saja barang yang paling diminati pembeli usia muda adalah ....', 'operasional', 'finansial', 'analitis', 'sekuensial', 'C', 'Analytical CRM menganalisis data riwayat transaksi konsumen untuk memetakan perilaku dan preferensi demografis pembeli.', 1),
  ('q-stsi4207-m7-tf1-10', 'set-stsi4207-m7-9', 'Petugas Call Centre menggunakan bagian CRM ....', 'Operasional', 'Finansial', 'Analitis', 'Sekuensial', 'A', 'Operational CRM menyediakan antarmuka bagi staf call centre untuk menangani interaksi langsung dan keluhan pelanggan.', 1),
  ('q-stsi4207-m7-tf2-01', 'set-stsi4207-m7-9', 'Model bisnis untuk toko online seperti Blibli.Com adalah ....', 'pengepul', 'pengecer', 'perantara', 'media sosial', 'B', 'Toko ritel daring (e-tailer) beroperasi sebagai pengecer digital yang menjual barang langsung ke konsumen pemakai.', 1),
  ('q-stsi4207-m7-tf2-02', 'set-stsi4207-m7-9', 'Tokopedia termasuk perusahaan dengan model bisnis ....', 'pengepul', 'pengecer', 'perantara', 'media sosial', 'C', 'Marketplace bertindak sebagai perantara transaksi (transaction broker) yang mempertemukan pihak penjual dan pembeli.', 1),
  ('q-stsi4207-m7-tf2-03', 'set-stsi4207-m7-9', 'Pembelian karet alam bagi perusahaan ban termasuk model perdagangan ....', 'C2C', 'G2G', 'B2C', 'B2B', 'D', 'Transaksi pengadaan material antarperusahaan manufaktur merupakan model Business-to-Business (B2B).', 1),
  ('q-stsi4207-m7-tf2-04', 'set-stsi4207-m7-9', 'Amazon termasuk model perdagangan ....', 'C2C', 'G2G', 'B2C', 'B2B', 'C', 'Amazon menyalurkan dan menjual produk langsung kepada konsumen perorangan dalam kerangka Business-to-Consumer (B2C).', 1),
  ('q-stsi4207-m7-tf2-05', 'set-stsi4207-m7-9', 'Pendapatan Google terbesar berasal dari ....', 'penjualan smartphone pixel', 'penjualan google drive', 'iklan', 'penjualan android', 'C', 'Sumber pendapatan terbesar raksasa teknologi Google diperoleh melalui bisnis penayangan iklan daring (Google Ads).', 1),
  ('q-stsi4207-m7-tf2-06', 'set-stsi4207-m7-9', 'Model pendapatan Joox adalah ....', 'premium', 'freemium', 'berlangganan', 'iklan', 'B', 'Model freemium memberikan akses gratis dengan keterbatasan tertentu serta opsi langganan berbayar untuk fitur premium.', 1),
  ('q-stsi4207-m7-tf2-07', 'set-stsi4207-m7-9', 'Traveloka, AirBnB, Tiket.com adalah contoh perusahaan yang menggunakan model bisnis ....', 'penyedia konten', 'pedagang eceran', 'penjual iklan', 'perantara transaksi', 'D', 'Aplikasi OTA memfasilitasi pemesanan kamar hotel dan tiket penerbangan dengan memperoleh komisi sebagai perantara transaksi.', 1),
  ('q-stsi4207-m7-tf2-08', 'set-stsi4207-m7-9', 'Youtube adalah contoh perusahaan yang menggunakan model bisnis ....', 'penyedia konten', 'pedagang eceran', 'penjual iklan', 'perantara transaksi', 'A', 'YouTube menyediakan wadah platform penyiaran dan distribusi video digital sebagai penyedia konten (content provider).', 1),
  ('q-stsi4207-m7-tf2-09', 'set-stsi4207-m7-9', 'Ruang Guru adalah contoh perusahaan yang menggunakan model bisnis ....', 'penyedia konten', 'pedagang eceran', 'penjual iklan', 'perantara transaksi', 'A', 'Ruangguru memproduksi materi pelajaran digital dan paket video bimbingan sebagai penyedia konten edukasi.', 1),
  ('q-stsi4207-m7-tf2-10', 'set-stsi4207-m7-9', 'Netflix mampu bersaing dengan Blockbuster karena meniadakan biaya sewa ....', 'kios', 'komputer', 'lahan', 'rumah', 'A', 'Model streaming video Netflix memangkas beban biaya sewa toko fisik (kios) kaset video yang membebani Blockbuster.', 1)
INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m8-tf1-01', 'set-stsi4207-m7-9', 'Menghitung gaji bulanan karyawan termasuk jenis keputusan ....', 'rasional', 'terstruktur', 'semi terstruktur', 'tidak terstruktur', 'B', 'Penghitungan gaji rutin memiliki rumus tetap dan aturan baku yang pasti, sehingga tergolong keputusan terstruktur (structured decision).', 1),
  ('q-stsi4207-m8-tf1-02', 'set-stsi4207-m7-9', 'Memilih pemasok untuk barang tertentu termasuk jenis keputusan ....', 'rasional', 'terstruktur', 'semi terstruktur', 'tidak terstruktur', 'C', 'Pemilihan pemasok memiliki kriteria terukur sekaligus membutuhkan penilaian subjektif dan negosiasi (semi terstruktur).', 1),
  ('q-stsi4207-m8-tf1-03', 'set-stsi4207-m7-9', 'Membuat produk baru termasuk jenis keputusan ....', 'rasional', 'terstruktur', 'semi terstruktur', 'tidak terstruktur', 'D', 'Peluncuran produk baru sarat ketidakpastian dan tidak memiliki formula baku otomatis, sehingga termasuk keputusan tidak terstruktur.', 1),
  ('q-stsi4207-m8-tf1-04', 'set-stsi4207-m7-9', 'Tiga kategori peran manajerial menurut Mintzberg adalah ....', 'interpersonal, informational, keputusan', 'pengendalian, kepemimpinan, pengawasan', 'operasional, manajerial, eksekutif', 'budaya, organisasional, teknis', 'A', 'Henry Mintzberg mengelompokkan peran manajerial ke dalam tiga ranah: Interpersonal, Informasional, dan Pengambilan Keputusan (Decisional).', 1),
  ('q-stsi4207-m8-tf1-05', 'set-stsi4207-m7-9', 'Menolak kebenaran informasi karena konsepsi yang dimiliki disebut ....', 'filter redaksional', 'filter reduksional', 'filter abrasif', 'filter manajerial', 'D', 'Filter manajerial mencerminkan praduga atau kerangka berpikir manajer yang menyaring dan menolak fakta yang tidak sesuai keyakinannya.', 1),
  ('q-stsi4207-m8-tf1-06', 'set-stsi4207-m7-9', 'Konsistensi struktur data merupakan dimensi kualitas data ....', 'integritas', 'akurasi', 'ketepatan waktu', 'kelengkapan', 'A', 'Integritas data (Data Integrity) merujuk pada konsistensi format, kebenaran relasi struktural, dan keutuhan data dalam basis data.', 1),
  ('q-stsi4207-m8-tf1-07', 'set-stsi4207-m7-9', 'Membuat anggaran merupakan perwujudan fungsi manajemen ....', 'perencanaan', 'pengendalian', 'koordinasi', 'pengawasan', 'A', 'Menyusun anggaran dan mengalokasikan proyeksi dana merupakan wujud konkret pelaksanaan fungsi perencanaan (planning).', 1),
  ('q-stsi4207-m8-tf1-08', 'set-stsi4207-m7-9', 'Memberikan surat peringatan pada karyawan yang melanggar aturan merupakan perwujudan fungsi manajemen ....', 'perencanaan', 'pengendalian', 'koordinasi', 'pengawasan', 'B', 'Tindakan korektif dan penegakan regulasi terhadap penyimpangan kerja merupakan perwujudan fungsi pengendalian (controlling).', 1),
  ('q-stsi4207-m8-tf1-09', 'set-stsi4207-m7-9', 'Membaca dan mempelajari laporan penjualan harian merupakan perwujudan fungsi manajemen ....', 'perencanaan', 'pengendalian', 'koordinasi', 'pengawasan', 'D', 'Meninjau laporan kemajuan harian untuk memantau performa terhadap sasaran adalah pelaksanaan fungsi pengawasan (monitoring).', 1),
  ('q-stsi4207-m8-tf1-10', 'set-stsi4207-m7-9', 'Mengajak diskusi karyawan yang mengalami penurunan kinerja untuk mencari tahu penyebabnya merupakan tahapan pembuatan keputusan ....', 'pencarian fakta', 'perancangan solusi', 'pemilihan alternatif solusi', 'penerapan solusi', 'A', 'Menyelidiki akar persoalan dan mengumpulkan data latar belakang merupakan fase pencarian fakta (Intelligence/Fact Finding).', 1),
  ('q-stsi4207-m8-tf2-01', 'set-stsi4207-m7-9', 'Analisis prediktif dapat digunakan untuk hal berikut, kecuali ....', 'mengantisipasi tanggapan pada produk baru', 'mengidentifikasi produk yang paling menguntungkan', 'menentukan rute pengiriman barang terbaik', 'menilai kelayakan kredit nasabah', 'D', 'Kelayakan kredit umumnya menggunakan sistem skoring berbasis aturan kaku, sedangkan analisis prediktif memproyeksikan kecenderungan masa depan.', 1),
  ('q-stsi4207-m8-tf2-02', 'set-stsi4207-m7-9', 'Dalam BSC, kinerja diukur berdasarkan ....', 'KIP', 'KPI', 'IKP', 'PIK', 'B', 'Balanced Scorecard (BSC) memonitor pencapaian target organisasi melalui indikator kinerja utama (Key Performance Indicators / KPI).', 1),
  ('q-stsi4207-m8-tf2-03', 'set-stsi4207-m7-9', 'Analisa sensitivitas banyak digunakan dalam sistem ....', 'DMS', 'DSS', 'DNS', 'NDA', 'B', 'Analisis sensitivitas (What-If analysis) merupakan kapabilitas inti dalam Decision Support System (DSS).', 1),
  ('q-stsi4207-m8-tf2-04', 'set-stsi4207-m7-9', 'Media untuk menampilkan kinerja perusahaan berdasarkan kriteria tertentu adalah ....', 'dashcam', 'scoring', 'dashboard', 'KPI', 'C', 'Dashboard visual menyajikan ringkasan indikator performa grafis agar mudah dievaluasi para pimpinan perusahaan.', 1),
  ('q-stsi4207-m8-tf2-05', 'set-stsi4207-m7-9', 'Yang tidak termasuk alat dalam analisis prediktif adalah ....', 'statistik', 'ekonometri', 'data mining', 'intuisi', 'D', 'Analisis prediktif mengandalkan metode kuantitatif matematis dan data empiris, bukan berdasarkan intuisi semata.', 1),
  ('q-stsi4207-m8-tf2-06', 'set-stsi4207-m7-9', 'Fasilitas untuk menelusuri data yang menjadi dasar suatu laporan disebut ....', 'drill down', 'throughput', 'drilling', 'data staging', 'A', 'Fitur drill-down memungkinkan pengguna menavigasi dari ringkasan laporan makro hingga ke perincian transaksi mikro.', 1),
  ('q-stsi4207-m8-tf2-07', 'set-stsi4207-m7-9', 'Menurunnya keterlambatan pengiriman barang merupakan KPI untuk Scorecard dalam dimensi ....', 'keuangan', 'pembelajaran dan pertumbuhan', 'proses Bisnis', 'pelanggan', 'C', 'Ketepatan waktu dan efisiensi rantai distribusi logistik dinilai dalam perspektif proses bisnis internal.', 1),
  ('q-stsi4207-m8-tf2-08', 'set-stsi4207-m7-9', 'Naiknya kas masuk merupakan KPI untuk Scorecard dalam dimensi ....', 'keuangan', 'pembelajaran dan pertumbuhan', 'proses Bisnis', 'pelanggan', 'A', 'Peningkatan arus kas masuk dan pendapatan dinilai langsung pada dimensi keuangan (financial perspective).', 1),
  ('q-stsi4207-m8-tf2-09', 'set-stsi4207-m7-9', 'Menurunnya piutang tidak tertagih merupakan KPI untuk Scorecard dalam dimensi ....', 'keuangan', 'pembelajaran dan pertumbuhan', 'proses Bisnis', 'pelanggan', 'A', 'Kolektibilitas piutang dan rasio kredit macet adalah indikator performa pada dimensi keuangan.', 1),
  ('q-stsi4207-m8-tf2-10', 'set-stsi4207-m7-9', 'Model yang dominan digunakan dalam DSS adalah ....', 'ikonik', 'mental', 'analog', 'matematis', 'D', 'Decision Support System (DSS) banyak menggunakan model matematis dan simulasi kuantitatif untuk mengevaluasi beragam alternatif keputusan bisnis.', 1),
  ('q-stsi4207-m9-tf1-01', 'set-stsi4207-m7-9', 'SDLC digunakan secara resmi sejak ....', '1960', '1970', '2010', '1980', 'B', 'System Development Life Cycle (SDLC) mulai diperkenalkan dan digunakan secara formal dalam rekayasa perangkat lunak dan sistem informasi pada era tahun 1970-an.', 1),
  ('q-stsi4207-m9-tf1-02', 'set-stsi4207-m7-9', 'Komputerisasi proses penggajian merupakan contoh ....', 'otomatisasi proses bisnis', 'rasionalisasi proses bisnis', 'perancangan ulang proses bisnis', 'pergeseran paradigma', 'A', 'Mengubah proses penggajian manual menjadi terkomputerisasi merupakan bentuk otomatisasi proses bisnis standar.', 1),
  ('q-stsi4207-m9-tf1-03', 'set-stsi4207-m7-9', 'Gojek merupakan contoh dari ....', 'otomatisasi proses bisnis', 'rasionalisasi proses bisnis', 'perancangan ulang proses bisnis', 'pergeseran paradigma', 'D', 'Gojek merevolusi model industri transportasi dan pemesanan layanan on-demand, sehingga termasuk dalam kategori pergeseran paradigma (paradigm shift).', 1),
  ('q-stsi4207-m9-tf1-04', 'set-stsi4207-m7-9', 'Pengembangan sistem pada masa tutup pembukuan tidak layak secara ....', 'teknis', 'hukum', 'ekonomis', 'jadwal', 'D', 'Melakukan implementasi atau migrasi sistem bertepatan dengan masa tutup buku dapat mengganggu operasional vital, sehingga dinilai tidak layak dari aspek jadwal (schedule feasibility).', 1),
  ('q-stsi4207-m9-tf1-05', 'set-stsi4207-m7-9', 'Jika suatu sistem informasi di perusahaan eceran membutuhkan komputer super, maka tidak layak secara ....', 'teknis', 'hukum', 'ekonomis', 'jadwal', 'A', 'Penggunaan superkomputer pada toko ritel umum dinilai tidak layak secara teknis (technical feasibility) karena spesifikasi infrastruktur berlebihan dan tidak selaras dengan arsitektur teknis yang diperlukan.', 1)
INSERT INTO public.questions (id, question_set_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, points)
VALUES
  ('q-stsi4207-m9-tf1-06', 'set-stsi4207-m7-9', 'Program penghitung pajak salah menerapkan tarif PPh Pasal 25 berarti tidak layak secara ....', 'teknis', 'hukum', 'ekonomis', 'jadwal', 'B', 'Kesalahan penerapan aturan perpajakan yang sah melanggar regulasi perundang-undangan sehingga sistem dinilai tidak layak secara hukum (legal feasibility).', 1),
  ('q-stsi4207-m9-tf1-07', 'set-stsi4207-m7-9', 'Pengembangan sistem informasi yang mahal dan lebih mahal daripada manfaatnya tidak layak secara ....', 'teknis', 'hukum', 'ekonomis', 'jadwal', 'C', 'Apabila total estimasi biaya lebih besar dibandingkan nilai manfaat yang dihasilkan (cost > benefit), sistem dinyatakan tidak layak secara ekonomis (economic feasibility).', 1),
  ('q-stsi4207-m9-tf1-08', 'set-stsi4207-m7-9', 'Pemangku kepentingan mana yang sebaiknya diikutsertakan dalam pengembangan sistem informasi ....', 'pemerintah', 'konsumen', 'pengguna', 'pemegang saham', 'C', 'Pengguna langsung (end-users) memegang peranan krusial untuk memastikan antarmuka dan fungsionalitas sistem baru sesuai dengan proses bisnis nyata di lapangan.', 1),
  ('q-stsi4207-m9-tf1-09', 'set-stsi4207-m7-9', 'Pemangku kepentingan yang terkait dengan kelayakan secara hukum ....', 'pemerintah', 'konsumen', 'pengguna', 'pemegang saham', 'A', 'Lembaga pemerintah merupakan regulator yang menerbitkan regulasi, undang-undang, serta standar kepatuhan hukum yang harus dipatuhi sistem informasi.', 1),
  ('q-stsi4207-m9-tf1-10', 'set-stsi4207-m7-9', 'Alat bantu aplikasi komputer untuk mengembangkan sistem informasi ....', 'CASE', 'CAST', 'CEASE', 'CARD', 'A', 'CASE (Computer-Aided Software Engineering) merupakan perangkat lunak otomatisasi yang mendukung proses pemodelan, perancangan, dan pembangkitan kode sistem.', 1),
  ('q-stsi4207-m9-tf2-01', 'set-stsi4207-m7-9', 'Ukuran kesuksesan proyek adalah ....', 'tepat waktu dan anggaran', 'anggaran dihabiskan', 'selesai lebih cepat', 'laporan lengkap', 'A', 'Tolok ukur keberhasilan proyek secara umum diukur dari ketepatan waktu penyelesaian (on-time), kepatuhan terhadap alokasi anggaran (on-budget), serta kesesuaian dengan ruang lingkup (on-scope).', 1),
  ('q-stsi4207-m9-tf2-02', 'set-stsi4207-m7-9', 'Yang bukan variabel utama keberhasilan proyek adalah ....', 'pemasok', 'risiko', 'waktu', 'kualitas', 'A', 'Lima variabel utama dalam manajemen proyek adalah ruang lingkup (scope), waktu (time), biaya (cost), kualitas (quality), dan risiko (risk). Pemasok merupakan pihak eksternal, bukan variabel kendali inti proyek.', 1),
  ('q-stsi4207-m9-tf2-03', 'set-stsi4207-m7-9', 'Keamanan sistem informasi masuk dalam kategori ....', 'must have', 'should have', 'could have', 'will not have', 'A', 'Menggunakan metode prioritas MoSCoW, keamanan data dan akses sistem informasi merupakan kebutuhan mutlak/kritis (must have) yang tidak dapat ditiadakan.', 1),
  ('q-stsi4207-m9-tf2-04', 'set-stsi4207-m7-9', 'Bagi perusahaan jasa, sistem informasi persediaan dagangan termasuk kategori ....', 'must have', 'should have', 'could have', 'will not have', 'D', 'Karena perusahaan jasa tidak menjual persediaan barang fisik berwujud, sistem inventarisasi barang dagangan masuk ke dalam kategori tidak diperlukan (''will not have'').', 1),
  ('q-stsi4207-m9-tf2-05', 'set-stsi4207-m7-9', 'Bagi perusahaan dagang, sistem informasi persediaan dagangan termasuk kategori ....', 'must have', 'should have', 'could have', 'will not have', 'A', 'Inti operasional perusahaan dagang bertumpu pada perputaran barang persediaan fisik, sehingga sistem informasi persediaan dagangan adalah syarat wajib (must have).', 1),
  ('q-stsi4207-m9-tf2-06', 'set-stsi4207-m7-9', 'Bagi perusahaan konsultan manajemen, sistem informasi pengadaan barang termasuk kategori ....', 'must have', 'should have', 'could have', 'will not have', 'C', 'Fokus bisnis konsultan manajemen adalah keahlian profesional dan layanan konsultasi non-fisik, sehingga pengadaan barang fisik hanya bernilai pendukung opsional (could have).', 1),
  ('q-stsi4207-m9-tf2-07', 'set-stsi4207-m7-9', 'Yang menunjukkan rencana dan realisasi proyek ....', 'CPM', 'PERT', 'Gantt Chart', 'Chart of Account', 'C', 'Gantt Chart menampilkan perbandingan visual secara berdampingan antara jadwal rencana kegiatan dan progres riil realisasi tahapan proyek pada lintasan waktu.', 1),
  ('q-stsi4207-m9-tf2-08', 'set-stsi4207-m7-9', 'Yang tidak menunjukkan titik kritis suatu proyek ....', 'CPM', 'PERT', 'Gantt Chart', 'Chart of Account', 'D', 'Chart of Account adalah daftar kode akun pembukuan akuntansi keuangan, bukan metodologi perencanaan jalur kritis (critical path) manajemen proyek.', 1),
  ('q-stsi4207-m9-tf2-09', 'set-stsi4207-m7-9', 'Ukuran proyek dinilai dengan ....', 'estimasi', 'prediksi', 'biaya dan waktu pengerjaan', 'intuisi', 'C', 'Besaran atau skala sebuah proyek dinilai secara kuantitatif melalui estimasi alokasi total biaya anggaran dan lama waktu pengerjaan proyek tersebut.', 1),
  ('q-stsi4207-m9-tf2-10', 'set-stsi4207-m7-9', 'Potensi munculnya masalah yang mengganggu penyelesaian proyek adalah ....', 'risiko', 'biaya', 'waktu', 'tenaga', 'A', 'Risiko proyek merupakan probabilitas timbulnya kejadian tak terduga yang dapat menghambat, menunda, atau menggagalkan ketercapaian target proyek.', 1)
